package me.pikanote.companion;

import android.content.*;import android.net.*;import android.net.wifi.WifiManager;
import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.*;

final class LanBoost implements AutoCloseable {
 final PikaService owner;final BleTransport ble;final ExecutorService worker=Executors.newSingleThreadExecutor();final ScheduledExecutorService deadlines=Executors.newSingleThreadScheduledExecutor(),networkPolicy=Executors.newSingleThreadScheduledExecutor();final java.util.concurrent.atomic.AtomicBoolean policyQueued=new java.util.concurrent.atomic.AtomicBoolean();volatile long lastOfferAt=0;
 android.os.PowerManager.WakeLock cpu;WifiManager.WifiLock wifiLock;
 volatile ServerSocket server;volatile Socket socket;volatile LanWire wire;volatile boolean closed=false;byte[] secret;final ConnectivityManager connectivity;final ConnectivityManager.NetworkCallback callback;volatile Network selectedNetwork;volatile long lastTransferAt=0;final WifiSsidPolicy.Observation ssidObservation=new WifiSsidPolicy.Observation();volatile boolean reoffer=false;final java.util.concurrent.atomic.AtomicBoolean offerQueued=new java.util.concurrent.atomic.AtomicBoolean();
 LanBoost(PikaService service,BleTransport transport){owner=service;ble=transport;if(service==null){connectivity=null;callback=null;return;}cpu=service.getSystemService(android.os.PowerManager.class).newWakeLock(android.os.PowerManager.PARTIAL_WAKE_LOCK,"Pika:transfer");cpu.setReferenceCounted(false);wifiLock=((WifiManager)service.getApplicationContext().getSystemService(Context.WIFI_SERVICE)).createWifiLock(WifiManager.WIFI_MODE_FULL_HIGH_PERF,"Pika:LAN");wifiLock.setReferenceCounted(false);connectivity=service.getSystemService(ConnectivityManager.class);callback=new ConnectivityManager.NetworkCallback(){@Override public void onAvailable(Network network){ble.handler.postDelayed(()->{if(!closed&&ble.online&&!online())offer();},800);}@Override public void onLost(Network network){ssidObservation.clear(network);if(network.equals(selectedNetwork))shutdown();}@Override public void onCapabilitiesChanged(Network network,NetworkCapabilities caps){checkPolicy();}};connectivity.registerNetworkCallback(new NetworkRequest.Builder().addTransportType(NetworkCapabilities.TRANSPORT_WIFI).build(),callback);networkPolicy.scheduleWithFixedDelay(this::checkPolicy,2,5,TimeUnit.SECONDS);}
 void traffic(){lastTransferAt=android.os.SystemClock.elapsedRealtime();if(cpu!=null)cpu.acquire(10000);}
 void releasePower(){if(cpu!=null&&cpu.isHeld())cpu.release();if(wifiLock!=null&&wifiLock.isHeld())wifiLock.release();if(ble.gatt!=null)try{ble.gatt.requestConnectionPriority(android.bluetooth.BluetoothGatt.CONNECTION_PRIORITY_HIGH);}catch(Exception ignored){}}
 boolean transferring(){return online()&&android.os.SystemClock.elapsedRealtime()-lastTransferAt<1500;}
 boolean online(){return wire!=null&&ble.online;}
 static JSONObject settings(Store store)throws Exception{synchronized(store){JSONObject secrets=store.state.optJSONObject("settingsSecrets");JSONObject config=secrets==null?null:secrets.optJSONObject("wifiBoost");return config==null?new JSONObject():new JSONObject(config.toString());}}
 static JSONObject summary(Store store)throws Exception{JSONObject config=settings(store);return new JSONObject().put("enabled",config.optBoolean("enabled")).put("ssid",config.optString("ssid")).put("passwordSaved",!config.optString("password").isEmpty()).put("active",PikaService.instance!=null&&PikaService.instance.ble!=null&&PikaService.instance.ble.lan.online());}
 static void save(Store store,JSONObject input)throws Exception{synchronized(store){JSONObject config=settings(store);String ssid=input.optString("ssid"),password=input.optString("password");if(ssid.getBytes("UTF-8").length>32||password.getBytes("UTF-8").length>63)throw new IOException("Check Wi-Fi name and password");if(input.optBoolean("enabled")&&ssid.isEmpty())throw new IOException("Enter the Wi-Fi network name");if(!ssid.equals(config.optString("ssid"))||!password.isEmpty()||input.optBoolean("open"))config.put("password",password);config.put("ssid",ssid).put("enabled",input.optBoolean("enabled"));JSONObject secrets=store.state.optJSONObject("settingsSecrets");if(secrets==null){secrets=new JSONObject();store.state.put("settingsSecrets",secrets);}secrets.put("wifiBoost",config);store.save();}PikaService service=PikaService.instance;if(service!=null){service.ble.lan.shutdown();service.ble.handler.postDelayed(service.ble.lan::offer,250);}}
 String currentSsid(){try{if(owner.checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){ssidObservation.clear(null);return "";}Network network=connectivity.getActiveNetwork();NetworkCapabilities caps=network==null?null:connectivity.getNetworkCapabilities(network);if(caps==null||!caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)){ssidObservation.clear(null);return "";}WifiManager wm=owner.getApplicationContext().getSystemService(WifiManager.class);String raw=wm.getConnectionInfo().getSSID();return ssidObservation.resolve(network,raw);}catch(Exception unavailable){return "";}}
 // Android redacts SSID in background. A foreground observation is valid only
 // for the same live Network handle; loss/change or revoked permission clears it.
 boolean eligible(){try{Network n=connectivity.getActiveNetwork();NetworkCapabilities caps=connectivity.getNetworkCapabilities(n);JSONObject config=settings(Store.get(owner));return config.optBoolean("enabled")&&n!=null&&caps!=null&&caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)&&WifiSsidPolicy.matches(config.optString("ssid"),currentSsid())&&(selectedNetwork==null||selectedNetwork.equals(n));}catch(Exception unavailable){return false;}}
 void checkPolicy(){if(closed||!policyQueued.compareAndSet(false,true))return;try{networkPolicy.execute(()->{try{currentSsid();if(ble.online){if(online()){if(!eligible())shutdown();}else if(!ble.deviceBusy&&!ble.preparingBulk&&eligible()){long now=android.os.SystemClock.elapsedRealtime();if(now-lastOfferAt>=5000){lastOfferAt=now;offer();}}}}finally{policyQueued.set(false);}});}catch(RejectedExecutionException stopped){policyQueued.set(false);}}
 void connected(){lastOfferAt=0;checkPolicy();}
 final Runnable verifyNetwork=this::checkPolicy;
 synchronized void offer(){if(closed||!ble.online||server!=null)return;if(!offerQueued.compareAndSet(false,true)){reoffer=true;return;}try{worker.execute(()->{try{startOffer();}catch(Exception e){android.util.Log.i("PikaLan","Wi-Fi boost unavailable: "+e.getClass().getSimpleName()+"; BLE remains active");}finally{offerQueued.set(false);if(reoffer&&!closed){reoffer=false;ble.handler.postDelayed(this::offer,250);}}});}catch(RejectedExecutionException closedWorker){offerQueued.set(false);}}
 void startOffer()throws Exception{
  shutdown();if(closed||!ble.online)return;JSONObject config=settings(Store.get(owner));if(!config.optBoolean("enabled"))return;
  ConnectivityManager cm=owner.getSystemService(ConnectivityManager.class);Network wifi=null;Inet4Address address=null;
  Network network=cm.getActiveNetwork();NetworkCapabilities caps=network==null?null:cm.getNetworkCapabilities(network);String phoneSsid=currentSsid();
  if(caps==null||!caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||!WifiSsidPolicy.matches(config.optString("ssid"),phoneSsid))return;
  LinkProperties links=cm.getLinkProperties(network);if(links!=null)for(LinkAddress link:links.getLinkAddresses())if(link.getAddress() instanceof Inet4Address&&!link.getAddress().isLoopbackAddress()){wifi=network;address=(Inet4Address)link.getAddress();break;}
  if(address==null)return;selectedNetwork=wifi;final long session=ble.session;final ServerSocket listener=new ServerSocket();listener.setReuseAddress(true);listener.bind(new InetSocketAddress(address,0),1);listener.setSoTimeout(12000);server=listener;secret=new byte[32];new SecureRandom().nextBytes(secret);
  JSONObject offer=new JSONObject().put("ssid",config.getString("ssid")).put("phoneSsid",WifiSsidPolicy.identity(phoneSsid)).put("ssidProof",true).put("password",config.optString("password")).put("host",address.getHostAddress()).put("port",listener.getLocalPort()).put("key",BleTransport.hex(secret));
  BleTransport.Reply reply=ble.rpc("/api/phone/lan","POST",offer.toString(),null);if(reply.status!=200||!ble.online||ble.session!=session){shutdown();return;}
  try{while(!closed&&ble.online&&ble.session==session&&server==listener){Socket client=listener.accept();client.setTcpNoDelay(true);client.setSoTimeout(8000);socket=client;boolean activated=false;
   try{byte[] challenge=new byte[32];new SecureRandom().nextBytes(challenge);client.getOutputStream().write(challenge);client.getOutputStream().flush();LanWire channel=new LanWire(client.getInputStream(),client.getOutputStream(),secret,challenge,true);if(!MessageDigest.isEqual(channel.read(),LanWire.HELLO))throw new IOException("Invalid LAN peer");
    // Switch data paths only between requests/streams: no BLE/LAN reordering.
    boolean locked=false;long until=android.os.SystemClock.elapsedRealtime()+7000;while(ble.online&&ble.session==session&&android.os.SystemClock.elapsedRealtime()<until){if(ble.rpcLock.tryLock(20,TimeUnit.MILLISECONDS)){if(ble.pending.isEmpty()&&ble.tunnels.isEmpty()&&ble.speech.isEmpty()){locked=true;break;}ble.rpcLock.unlock();}Thread.sleep(10);}if(!locked)throw new IOException("BLE busy");try{if(!ble.online||ble.session!=session)throw new IOException("BLE disconnected");if(!eligible())throw new IOException("Wi-Fi name changed; keeping BLE");
    channel.write("OK".getBytes("US-ASCII"));if(!MessageDigest.isEqual(channel.read(),("READY:"+config.getString("ssid")).getBytes("UTF-8")))throw new IOException("LAN not ready");wire=channel;activated=true;ble.handler.removeCallbacks(verifyNetwork);ble.handler.postDelayed(verifyNetwork,1500);if(wifiLock!=null)wifiLock.acquire();traffic();if(ble.gatt!=null)ble.gatt.requestConnectionPriority(android.bluetooth.BluetoothGatt.CONNECTION_PRIORITY_BALANCED);}finally{ble.rpcLock.unlock();}client.setSoTimeout(0);owner.status="Pika connected · Wi-Fi boost";owner.notifyStatus();android.util.Log.i("PikaLan","Fast channel ready");owner.enqueueBackgroundSync();
    for(;;){byte[] frame=channel.read();if(!ble.online||ble.session!=session)break;if(frame.length>=6&&((frame[0]&127)==23||(frame[0]&127)==25))android.util.Log.i("PikaLanRpc","RX op="+(frame[0]&127)+" ch="+(frame[1]&255)+" n="+(frame.length-6));if(frame.length>6)traffic();ble.receive(frame);}
   }catch(Exception failure){android.util.Log.i("PikaLan","Channel ended: "+failure.getClass().getSimpleName()+": "+failure.getMessage());}finally{boolean active=wire!=null;wire=null;releasePower();try{client.close();}catch(Exception ignored){}socket=null;if(active&&ble.online&&ble.session==session){for(BleTransport.Rpc pending:ble.pending.values())pending.done.completeExceptionally(new IOException("Wi-Fi interrupted; retrying over Bluetooth"));owner.status="Pika connected";owner.notifyStatus();owner.enqueueBackgroundSync();} }
  if(activated)break;}}finally{if(server==listener)shutdown();}
 }
 void send(int op,int id,byte[] data,int sequence)throws Exception{LanWire channel=wire;Socket client=socket;if(channel==null||client==null)throw new IOException("Wi-Fi unavailable");try{int offset=0;do{int count=Math.min(4000,data.length-offset);byte[] frame=new byte[count+6];frame[0]=(byte)(op|((offset+count==data.length)?128:0));frame[1]=(byte)id;frame[2]=(byte)sequence;frame[3]=(byte)(sequence>>8);frame[4]=(byte)count;frame[5]=(byte)(count>>8);System.arraycopy(data,offset,frame,6,count);ScheduledFuture<?> timeout=deadlines.schedule(()->{try{client.close();}catch(Exception ignored){}},3,TimeUnit.SECONDS);try{channel.write(frame);}finally{timeout.cancel(false);}if(count>0)traffic();offset+=count;}while(offset<data.length);}catch(Exception error){try{client.close();}catch(Exception ignored){}throw error;}}

 void shutdown(){ble.handler.removeCallbacks(verifyNetwork);selectedNetwork=null;boolean active=wire!=null;wire=null;releasePower();Socket client=socket;socket=null;if(client!=null)try{client.close();}catch(Exception ignored){}ServerSocket listener=server;server=null;if(listener!=null)try{listener.close();}catch(Exception ignored){}if(active&&ble.online&&!closed){for(BleTransport.Rpc pending:ble.pending.values())pending.done.completeExceptionally(new IOException("Wi-Fi interrupted; retrying over Bluetooth"));owner.status="Pika connected";owner.notifyStatus();owner.enqueueBackgroundSync();}}
 @Override public void close(){closed=true;networkPolicy.shutdownNow();try{connectivity.unregisterNetworkCallback(callback);}catch(Exception ignored){}shutdown();worker.shutdownNow();deadlines.shutdownNow();}
}
